SELECT id, session_id, `role`, content, image_url, created_at
FROM t_ai_message
WHERE session_id = #{sessionId}
ORDER BY id DESC
LIMIT #{limit}

SELECT id, session_id, `role`, content, image_url, created_at
FROM t_ai_message
WHERE session_id = #{sessionId} AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}
